#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles (transpose B tile to avoid bank conflicts)
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Row and column of C element
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Register accumulators
    float sum[UNROLL_FACTOR];
    for (int i = 0; i < UNROLL_FACTOR; i++) {
        sum[i] = 0.0f;
    }

    // Loop over tiles with unrolling
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {
        // Load tiles into shared memory
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int t_index = t + i;
            if (t_index < num_tiles) {
                int tiled_col = t_index * TILE_SIZE + tx;
                int tiled_row = t_index * TILE_SIZE + ty;

                if (row < N && tiled_col < N) {
                    As[ty][tx] = A[row * N + tiled_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                if (tiled_row < N && col < N) {
                    // Store B tile transposed to avoid bank conflicts
                    Bs[tx][ty] = B[tiled_row * N + col];
                } else {
                    Bs[tx][ty] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial dot products with unrolling
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[ty][k];
            for (int i = 0; i < UNROLL_FACTOR; i++) {
                int t_index = t + i;
                if (t_index < num_tiles) {
                    // Access transposed B tile
                    float b_val = Bs[k][tx];
                    sum[i] += a_val * b_val;
                }
            }
        }

        __syncthreads();
    }

    // Write result to C
    if (row < N && col < N) {
        float total = 0.0f;
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            total += sum[i];
        }
        C[row * N + col] = total;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Set grid and block dimensions
    dim3 block_size(TILE_SIZE, TILE_SIZE / UNROLL_FACTOR);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), 
                                            B.data_ptr<float>(), 
                                            C.data_ptr<float>(), 
                                            N);

    return C;
}
"""

